package com.zhibrary.borrow;
import org.springframework.data.jpa.repository.JpaRepository; import java.util.*;
public interface BorrowRepository extends JpaRepository<BorrowRecord,Long>{List<BorrowRecord> findByUserUsernameOrderByBorrowedDateDesc(String username); List<BorrowRecord> findByStatus(BorrowStatus status); long countByStatus(BorrowStatus status); boolean existsByBookId(Long bookId); boolean existsByBookIdAndStatus(Long bookId, BorrowStatus status); @org.springframework.data.jpa.repository.Lock(jakarta.persistence.LockModeType.PESSIMISTIC_WRITE) @org.springframework.data.jpa.repository.Query("select r from BorrowRecord r where r.id = :id") Optional<BorrowRecord> lockById(@org.springframework.data.repository.query.Param("id") Long id);}
